_NUM = re.compile(r"-?\d+\.?\d*")


def _signature(path: str) -> tuple[float, ...]:
    """Scale-invariant fingerprint, so a different font-size still matches."""
    nums = [float(n) for n in _NUM.findall(path)]
    if not nums:
        return ()
    scale = max(abs(n) for n in nums) or 1.0
    return tuple(round(n / scale, 3) for n in nums)


_DIGIT_BY_SIGNATURE = {_signature(p): d for p, d in DIGIT_BY_PATH.items()}


def digit_for_path(path: str) -> str | None:
    """Return the digit this glyph draws, or None if it isn't a digit.

    Unknown paths are the page's icons, so returning None here is also what
    filters chrome out of the question.
    """
    if not path:
        return None
    exact = DIGIT_BY_PATH.get(path)
    if exact is not None:
        return exact
    return _DIGIT_BY_SIGNATURE.get(_signature(path))
